INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/mqtt/3-取消订阅.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"b4672bf079a24b2e96bd11e4b56690af\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"2c51a560865e43feb93fcc3fcc725991\",\r\n  \"name\" : \"3-取消订阅\",\r\n  \"createTime\" : 1760064783745,\r\n  \"updateTime\" : 1757343506712,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"unsubscribe\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport mqtt;\r\n\r\n// 订阅主题\r\nmqtt.cs.unSubscribe(\'xuhy\');\r\n ');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/mqtt/4-集群订阅主题.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"20cf54914b7b408eab476e3ec7dea1cd\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"2c51a560865e43feb93fcc3fcc725991\",\r\n  \"name\" : \"4-集群订阅主题\",\r\n  \"createTime\" : 1760064783750,\r\n  \"updateTime\" : 1757345360437,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"cluster/subscribe\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 200,\\n    \\\"message\\\": \\\"success\\\",\\n    \\\"data\\\": null,\\n    \\\"timestamp\\\": 1757345225172,\\n    \\\"executeTime\\\": 32\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport mqtt;\r\n\r\n/**\r\n * 每次只允许，一个消费组 执行逻辑\r\n */\r\n\r\n\r\nasync mqtt.cs.clusterSubscribe(\"cluster\",\"xuhaiyang\",(topicName,stringContent,byteArrayContent)->{\r\n    println(\"2===========================>>>>>>\"+stringContent)\r\n});\r\n\r\nasync mqtt.cs.clusterSubscribe(\"cluster\",\"xuhaiyang\",(topicName,stringContent,byteArrayContent)->{\r\n    println(\"3===========================>>>>>>\"+stringContent)\r\n});\r\n\r\nasync mqtt.cs.clusterSubscribe(\"cluster\",\"xuhaiyang\",(topicName,stringContent,byteArrayContent)->{\r\n    println(\"1===========================>>>>>>\"+stringContent)\r\n});\r\n ');
