INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/01-String类型存取.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"fbfb535e80e747a39f601133e4220bf3\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"01-String类型存取\",\r\n  \"createTime\" : 1760064783766,\r\n  \"updateTime\" : 1749089668890,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"string\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\n// 测试的key:value数据写入\r\nredis.tet.putString(\'xuhaiyang\',\'test1\');\r\n\r\n// 测试的带有过期时间的key:value\r\n// -1:标识永久有效; 其他数值（num）:表示多少秒后key:value将失效被删除;\r\n// 第三个参数的单位是 秒\r\nredis.tet.putString(\'xuhaiyang\',\'test2\', -1);\r\n\r\n// 查询值\r\nredis.tet.getString(\'xuhaiyang\')\r\n\r\n// 当 redisKey 不存在的时候才会被插入\r\nredis.tet.putStringIfAbsent(\'xuhaiyang\',\'test3\');\r\n\r\n// 删除信息\r\nredis.tet.remove(\"xuhaiyang\")\r\n\r\n// 当 redisKey 不存在的时候才会被插入,插入后的值只能在20秒内能查询到\r\nredis.tet.putStringIfAbsent(\'xuhaiyang\',\'test3\', 20);\r\n\r\n// 查询值\r\nreturn redis.tet.getString(\'xuhaiyang\')\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/02-计数器.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"3f498c95dc9140f8a32872e820ea6976\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"02-计数器\",\r\n  \"createTime\" : 1760064783770,\r\n  \"updateTime\" : 1749089700100,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"increment\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\nredis.tet.remove(\"xuhaiyang1\");\r\n// 测试永久有效计数器\r\n// 第一次调用不存在 xuhaiyang1 这个key时候，返回 1\r\nredis.tet.getAndIncrement(\'xuhaiyang1\',-1);\r\n\r\n// 每次调用累加1 返回 2\r\nredis.tet.getAndIncrement(\'xuhaiyang1\',-1);\r\n\r\n// 每次调用累加1  返回 3\r\nredis.tet.getAndIncrement(\'xuhaiyang1\',-1);\r\n\r\n// 查询值\r\n// return redis.tet.getString(\'xuhaiyang1\')\r\n\r\n// 自定义累加值, 返回 5\r\nredis.tet.getAndIncrement(\'xuhaiyang1\',2,-1);\r\n\r\n// 自定义累加一个负值, 返回 1\r\nredis.tet.getAndIncrement(\'xuhaiyang1\',-4,-1);\r\n// ----------------------------------------------------------------------\r\n\r\n// 如果希望累加器，过一个指定的时间就移除\r\n// 直接配置一个过期时间（这里表示累加器只能存活200秒，过期后直接删除）\r\nredis.tet.getAndIncrement(\'xuhaiyang1\',10);\r\n\r\n// 查询值\r\nreturn redis.tet.getString(\'xuhaiyang1\')\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/03-Map类型数据存取.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"2b4db6b7e3554ffabdf65e57bf8bc2f3\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"03-Map类型数据存取\",\r\n  \"createTime\" : 1760064783774,\r\n  \"updateTime\" : 1749089725154,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"map\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\nredis.tet.remove(\"xuhaiyang2\");\r\n\r\n// 获取map操作对象（同时也是返回的数据结果集）(这里的map中的数值共用一个 统一 的 有效期)\r\n// -1：表示永久有效map；>0 : 表示map数据指定时间内有效\r\nvar mapObj = redis.tet.getMap(\'xuhaiyang2\',-1);\r\n\r\n// 添加一个json类型的数据\r\nredis.tet.saveOrUpdateMap(mapObj,\"1\",{\"name\":\"xuhaiyang1\",sex:\"男1\"})\r\n// 添加一个json类型的数据\r\nredis.tet.saveOrUpdateMap(mapObj,\"2\",{\"name\":\"xuhaiyang2\",sex:\"男2\"})\r\n// 添加一个json类型的数据\r\nredis.tet.saveOrUpdateMap(mapObj,\"a2\",{\"name\":\"xuhaiyanga2\",sex:\"男a2\"})\r\n// 添加一个json类型的数据\r\nredis.tet.saveOrUpdateMap(mapObj,\"b2\",{\"name\":\"xuhaiyangb2\",sex:\"男b2\"})\r\n\r\n// 更新一个json类型的数据\r\nredis.tet.saveOrUpdateMap(mapObj,\"1\",{\"name\":\"xuhaiyang11\",sex:\"男11\"})\r\n\r\n// 删除key中含有 1 的所有值\r\nredis.tet.delMapByMapkey(mapObj,\"*1*\")\r\n\r\n//模糊查询key中含有 2 的所有值\r\n// return redis.tet.getMapByMapkey(mapObj,\"*2*\")\r\n\r\n// // 打印数据\r\n// for(key,value in mapObj){\r\n//      println(\"key:\"+key+\",value:\"+value)\r\n// }\r\n\r\n//返回结果集\r\nreturn mapObj;');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/04-MapCache类型数据存取.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"30a42cb0bf094bb7bfbd49f7f97eb279\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"04-MapCache类型数据存取\",\r\n  \"createTime\" : 1760064783778,\r\n  \"updateTime\" : 1749089741776,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"mapcache\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\nredis.tet.remove(\"xuhaiyang3\");\r\n\r\n// 获取map操作对象（同时也是返回的数据结果集）\r\n// 这里的map中的数值 可以一个 key val 使用一个 有效期\r\nvar mapObj = redis.tet.getMapCache(\'xuhaiyang3\');\r\n\r\n// 添加一个json类型的永久数据\r\nredis.tet.saveOrUpdateMapCache(mapObj,\"1\",{\"name\":\"xuhaiyang1\",sex:\"男1\"}, -1)\r\n// 添加一个json类型的存活时间为20秒的数据\r\nredis.tet.saveOrUpdateMapCache(mapObj,\"2\",{\"name\":\"xuhaiyang2\",sex:\"男2\"}, 20)\r\n// 添加一个json类型的永久数据\r\nredis.tet.saveOrUpdateMapCache(mapObj,\"a2\",{\"name\":\"xuhaiyanga2\",sex:\"男a2\"},-1)\r\n// 添加一个json类型的永久数据\r\nredis.tet.saveOrUpdateMapCache(mapObj,\"b2\",{\"name\":\"xuhaiyangb2\",sex:\"男b2\"}, -1)\r\n\r\n// 更新一个json类型的数据\r\nredis.tet.saveOrUpdateMapCache(mapObj,\"1\",{\"name\":\"xuhaiyang11\",sex:\"男11\"}, -1)\r\n\r\n// 删除key中含有 1 的所有值\r\nredis.tet.delMapCacheByMapkey(mapObj,\"*1*\")\r\n\r\n//模糊查询key中含有 2 的所有值\r\n// return redis.tet.getMapCacheByMapkey(mapObj,\"*2*\")\r\n\r\n// // 打印数据\r\n// for(key,value in mapObj){\r\n//      println(\"key:\"+key+\",value:\"+value)\r\n// }\r\n\r\n//返回结果集\r\nreturn mapObj;');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/05-List类型数据存取.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"4ebbff7fb6ad4ecc93a5c91bfe097b70\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"05-List类型数据存取\",\r\n  \"createTime\" : 1760064783783,\r\n  \"updateTime\" : 1749089747682,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"list\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\nredis.tet.remove(\"xuhaiyang4\");\r\n\r\n// 获取list操作对象（同时也是返回的数据结果集）(这里的list中的数值共用一个 统一 的 有效期)\r\n// -1：表示永久有效list；>0 : 表示list数据指定时间内有效\r\nvar listObj = redis.tet.getList(\'xuhaiyang4\',-1);\r\n\r\n// 添加json类型的数据\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyang1\",sex:\"男1\"})\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyang2\",sex:\"男2\"})\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyang3\",sex:\"男3\"})\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyang4\",sex:\"男4\"})\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyanga2\",sex:\"男a2\"})\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyangb3\",sex:\"男b3\"})\r\nredis.tet.addList(listObj,{\"name\":\"xuhaiyangd4\",sex:\"男d4\"})\r\n\r\n// 删除value中含有 1 的所有值\r\n// redis.tet.delList(listObj,\".*1.*\")\r\n\r\n// 模糊查询value中含有 2 的所有值\r\n// return redis.tet.getListByValStr(listObj,\".*a2.*\")\r\n\r\n// // 打印数据\r\n// for(value in listObj){\r\n//      println(\"value:\"+value)\r\n// }\r\n\r\n//返回结果集\r\nreturn listObj;');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/06-Set类型数据存取.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"797a174a990c45d992fe1ac1b264125a\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"06-Set类型数据存取\",\r\n  \"createTime\" : 1760064783787,\r\n  \"updateTime\" : 1749089756108,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"set\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\nredis.tet.remove(\"xuhaiyang5\");\r\n\r\n// 获取set操作对象（同时也是返回的数据结果集）(这里的set中的数值共用一个 统一 的 有效期)\r\n// -1：表示永久有效list；>0 : 表示map数据指定时间内有效\r\nvar setObj = redis.tet.getSet(\'xuhaiyang5\',-1);\r\n\r\n// 添加json类型的数据\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyang1\",sex:\"男1\"})\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyang2\",sex:\"男2\"})\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyang3\",sex:\"男3\"})\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyang4\",sex:\"男4\"})\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyanga2\",sex:\"男a2\"})\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyangb3\",sex:\"男b3\"})\r\nredis.tet.addSet(setObj,{\"name\":\"xuhaiyangd4\",sex:\"男d4\"})\r\n\r\n// 删除value中含有 1 的所有值\r\nredis.tet.delSet(setObj,\".*1.*\")\r\n\r\n// 模糊查询value中含有 2 的所有值\r\n// return redis.tet.getSetByValStr(setObj,\".*a2.*\")\r\n\r\n// // 打印数据\r\n// for(value in setObj){\r\n//      println(\"value:\"+value)\r\n// }\r\n\r\n//返回结果集\r\nreturn setObj;');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/07-ScoreSortedSet类型数据存取.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"0bb8a7edb8be44ae81d50bc28f24267a\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"07-ScoreSortedSet类型数据存取\",\r\n  \"createTime\" : 1760064783791,\r\n  \"updateTime\" : 1749089759427,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"scoresortedset\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\nredis.tet.remove(\"xuhaiyang6\");\r\n\r\n// 获取set操作对象(这里的set中的数值共用一个 统一 的 有效期)\r\n// -1：表示永久有效list；>0 : 表示map数据指定时间内有效\r\n// 注意：\r\n//     这里返回的是操作对象，不是数据结果信息\r\nvar setObj = redis.tet.getScoreSet(\'xuhaiyang6\',-1);\r\n\r\n// 添加json类型的数据\r\nredis.tet.addScoreSet(setObj,1.0,{\"name\":\"xuhaiyang1\",sex:\"男1\"})\r\nredis.tet.addScoreSet(setObj,2.0,{\"name\":\"xuhaiyang2\",sex:\"男2\"})\r\nredis.tet.addScoreSet(setObj,3.0,{\"name\":\"xuhaiyang3\",sex:\"男3\"})\r\nredis.tet.addScoreSet(setObj,4.0,{\"name\":\"xuhaiyang4\",sex:\"男4\"})\r\nredis.tet.addScoreSet(setObj,7.0,{\"name\":\"xuhaiyanga2\",sex:\"男a2\"})\r\nredis.tet.addScoreSet(setObj,6.0,{\"name\":\"xuhaiyangb3\",sex:\"男b3\"})\r\nredis.tet.addScoreSet(setObj,5.0,{\"name\":\"xuhaiyangd4\",sex:\"男d4\"})\r\n\r\n// 删除value中含有 1 的所有值\r\nredis.tet.delScoreSet(setObj,\".*1.*\")\r\n\r\n// 模糊查询value中含有 2 的所有值\r\n//  return redis.tet.getSetByValStr(setObj,\".*2.*\")\r\n\r\n// 获取score降序序后的值\r\n//  return redis.tet.getScoreSetByDescScore(setObj)\r\n\r\n// 获取score升序序后的值\r\n//  return redis.tet.getScoreSetByAscScore(setObj)\r\n\r\n// 按照score的数值升序排序,后获取区间索引内的全部Set<Object>数据\r\n//  return redis.tet.getAscScoreSetByBetweenScore(setObj,0 ,3)\r\n\r\n// 按照score的数值降序排序,后获取区间索引内的全部Set<Object>数据\r\n return redis.tet.getDescScoreSetByBetweenScore(setObj,3 ,7)');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/08-数据订阅发布.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"2694b193f9054521ad75816ca35d9530\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"08-数据订阅发布\",\r\n  \"createTime\" : 1760064783796,\r\n  \"updateTime\" : 1749089765738,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"listenerAndPublish\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\n// 订阅topic数据，\r\n// 第一个参数： 自定义一个唯一的字符串，用于取消订阅时候\r\n// 第二个参数： topic的名称\r\n// 第三个参数： 回调函数，处理定于的数据\r\nredis.tet.listenerTopicName(\"peter\",\"xuhaiyang7\",(topicName,content)->{\r\n    println(content)\r\n});\r\n\r\n// // 写入topic数据\r\n// redis.tet.publish(\"xuhaiyang7\",\"我是徐海洋7！！！！！\")\r\n\r\n// // 取消单次订阅\r\n// // 第一个参数： 订阅的时候设置的 自定义一个唯一的字符串\r\n// // 第二个参数： topic的名称\r\n// redis.tet.delTopicListener(\"peter\",\"xuhaiyang7\")\r\n\r\n// 取消同一个topic的 全部订阅\r\n// 第一个参数： 订阅的时候设置的 自定义一个唯一的字符串\r\n// 第二个参数： topic的名称\r\n// redis.tet.delTopicAllListener(\"xuhaiyang7\");\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/09-限流服务.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"1fbf9003c85d4bcfa08cbe1377ffb878\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"09-限流服务\",\r\n  \"createTime\" : 1760064783799,\r\n  \"updateTime\" : 1749089771002,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"ratelimiter\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\nimport \'@get:/OnlineManual/rdbms/sql/list\' as list;\r\n\r\n// 创建一个限流器\r\n// 每秒只能访问一次\r\n  redis.tet.createRateLimiter(\"rdbms_sql_list\",1,\'s\')\r\n\r\n// 删除限流器\r\n//  redis.tet.deleteRateLimiter(\"rdbms_sql_list\")\r\n\r\n// 封装一个限流方法，使用上面的限流器\r\nreturn redis.tet.accessLimitedMethod(\"rdbms_sql_list\",()->{\r\n    // 调用被限流的指定服务\r\n    return list();\r\n})\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/10-数据同步.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"d83a518513504012bff2eb4206cfe822\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"10-数据同步\",\r\n  \"createTime\" : 1760064783803,\r\n  \"updateTime\" : 1749089797935,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"data\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport redis;\r\n\r\n\r\n/**\r\n *  将数据库中的数据同步到缓存\r\n *  1、 如果缓存中没有就查询并放入缓存，后再返回\r\n *  2、 如果缓存中有，直接返回数据\r\n */\r\nvar map = redis.tet.syncData2Cache(\"user_info\",()->{\r\n     var list = db.table(\'test\').column(\'*\').select();\r\n     var keys = [];\r\n     for(rowData in list){\r\n         println(\"------------------------\"+rowData.id)\r\n        keys.add(rowData.id);\r\n     }\r\n     return keys;\r\n},(key)->{\r\n        var list = db.list(\"select * from test where id=#{id}\",{id:key})\r\n        if(list.getLength() > 0 ){\r\n            return list.get(0);\r\n        }\r\n        return null;\r\n})\r\n\r\n// // 如果想要更新某一个id的数据，先删除\r\n// map.remove(\"1\");\r\n\r\n return map.get(\"1\");\r\n\r\n\r\n//-------------------------------------------------------------------------------------------------\r\n\r\n/**\r\n * 将缓存数据同步到其他数据库或者存储器上\r\n */\r\nvar map = redis.tet.syncCacheData2External(\"user_info\", (key,val)->{\r\n    // 这里根据实际的情况来将缓存数据同步到其他存储器上\r\n    println(\"插入数据key：\"+key+\";value:\"+val::stringify);\r\n\r\n},(key)->{\r\n     // 这里根据实际的情况来同步删除其他存储器上对应的数据\r\n    println(\"删除数据key：\"+key);\r\n});\r\n\r\nMap _map = {\"aaa\":{ \"id\": \"aaa\",  \"name\": \"aaaaaaaaa\"},\"bbb\":{ \"id\": \"bbb\", \"name\": \"bbbbbbbbb\"}};\r\n \r\nmap.putAll(_map);\r\n\r\nmap.remove(\"aaa\");\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/redis/group.json', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"1a50946495f943f6b74af5a753844a81\",\r\n  \"name\" : \"redis\",\r\n  \"type\" : \"api\",\r\n  \"parentId\" : \"e1295895dc814872927351d52a122809\",\r\n  \"path\" : \"redis\",\r\n  \"createTime\" : 1760064783472,\r\n  \"updateTime\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"paths\" : [ ],\r\n  \"options\" : [ ]\r\n}');
