INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/01-插件使用示例/tcp/1-创建TCP服务端.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"d4b8ce254d7e4699be05a896b597551f\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"af115bebf6e24a749d83ae79a42cfdb4\",\r\n  \"name\" : \"1-创建TCP服务端\",\r\n  \"createTime\" : 1760064783806,\r\n  \"updateTime\" : 1749317493686,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"server\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 200,\\n    \\\"message\\\": \\\"初始化TCP服务成功！\\\",\\n    \\\"data\\\": null,\\n    \\\"timestamp\\\": 1749317490421,\\n    \\\"executeTime\\\": 23\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport tcp;\r\ntcp.local_server.shutdown();\r\ntcp.local_server.init((message, channel, body) -> {\r\n\r\n    println(\"------服务端收到{\'业务类型\':\'\" + message.getType() + \"\',\'版本号\':\'\" + message.getVersion() + \"\'}的数据：\" + body)\r\n});\r\nvar channels = tcp.local_server.getAllChannelCache();\r\nfor (key, val in channels) {\r\n    println(key)\r\n}\r\n\r\n\r\nexit 200, \"初始化TCP服务成功！\";');
