INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/02-基础功能示例/4、Http使用/4.1-调用远程接口.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"e1403c7fc5c54791ad1376e173dcaf7d\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e73901107de641efbf48c1b8875093f1\",\r\n  \"name\" : \"4.1-调用远程接口\",\r\n  \"createTime\" : 1760064783848,\r\n  \"updateTime\" : 1749429696926,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"remoteAPI\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 200,\\n    \\\"message\\\": \\\"success\\\",\\n    \\\"data\\\": \\\"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJleHAiOjE3NDk0NzI4NzUsInVzZXJfbmFtZSI6InFpbmd5YW55dWFuXzQiLCJqdGkiOiI5OTk4Mjk2Yi02NDI3LTQ1ODYtOTcxNC1hOTkzYzA1M2Y3ZGMiLCJjbGllbnRfaWQiOiJmcm9udGVuZCIsInNjb3BlIjpbImFsbCJdfQ.CU5KtsuWypByB1DZdkNrd8qMVpoSliK0ymmi9rgp0lo\\\",\\n    \\\"timestamp\\\": 1749429676261,\\n    \\\"executeTime\\\": 1069\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport http;\r\nimport request;\r\n\r\nvar md5 = request.invokeFunction(\"/utils/buildMD5\",{input:\"*9IamI^ml\"});\r\n\r\nvar token = http.connect(\'https://36.150.156.12:9001/v2x/platform/auth/user/login\')\r\n    .body({\r\n        \"grantType\" : \"password\",\r\n        \"clientId\" : \"frontend\",\r\n        \"username\" : \"qingyanyuan_4\",\r\n        \"password\" : md5\r\n    })\r\n    .post().getBody().data.accessToken;\r\n\r\n// post 请求\r\nvar result = http.connect(\'https://36.150.156.12:9001/v2x/platform/device/monitor/overview/rscu?zoneId=1\')\r\n    .header(\"Authorization\", \"Bearer \" + token)\r\n    .get()\r\n    .getBody().data;\r\n\r\nresult[\'desc\'] = \'设备总数:\' + result.total + \';在线数量:\' + result.active + \';设备在线率:\' + result.onlineRate*100 + \'%\';\r\n\r\nreturn result;');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/02-基础功能示例/4、Http使用/4.2-表数据导出简单excel.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"095fcab386664dbd8a2e591c656b3e80\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e73901107de641efbf48c1b8875093f1\",\r\n  \"name\" : \"4.2-表数据导出简单excel\",\r\n  \"createTime\" : 1760064783852,\r\n  \"updateTime\" : 1750299019703,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"tableData2SampleExcel\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 500,\\n    \\\"message\\\": \\\"系统内部出现错误\\\",\\n    \\\"data\\\": null,\\n    \\\"timestamp\\\": 1750225051825,\\n    \\\"executeTime\\\": 133\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\n import response;\r\n\r\n return response.exportExcel(\r\n     \"徐海洋测试\" // 导出的 excel 文件的名称\r\n     , \"角色表\" // excel 第一行的大标题 名称\r\n     , () -> { // 分页钩子函数，自动分页查询，直至全部数据检索完成\r\n         return db.normal().select(\"select * from sys_role\")\r\n     }\r\n    // , \"0,5,test1;6,11,test2\" // 这里表示，在开头第二行，合并0至5列并填写上内容 test1 ；再合并6至11列并填写上内容 test2\r\n    // ,\"0,5,test3;6,11,test4\" // 这里表示，在开头第三行，合并0至5列并填写上内容 test3 ；再合并6至11列并填写上内容 test4\r\n    // ... 根据情况自行设计\r\n )');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/02-基础功能示例/4、Http使用/4.3-表数据导出复杂excel.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"745abc6a31fa409687be56acde11f8f5\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"e73901107de641efbf48c1b8875093f1\",\r\n  \"name\" : \"4.3-表数据导出复杂excel\",\r\n  \"createTime\" : 1760064783855,\r\n  \"updateTime\" : 1750298495619,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"tableData2ComplexExcel\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 200,\\n    \\\"message\\\": \\\"success\\\",\\n    \\\"data\\\": 6,\\n    \\\"timestamp\\\": 1750295942823,\\n    \\\"executeTime\\\": 7\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\n import response;\r\n\r\n return response.exportPageExcel(\r\n    \"徐海洋测试\" // 导出的 excel 文件的名称\r\n    , \"角色表\" // excel 第一行的大标题 名称\r\n    , (pageNum,pageSize) -> {  // 分页钩子函数，自动分页查询，直至全部数据检索完成\r\n        // 分页查询\r\n        var pageList = db.normal().select(\"\"\"\r\n            SELECT * \r\n            FROM sys_role\r\n            LIMIT ${pageSize} OFFSET ${(pageNum - 1) * pageSize}\r\n        \"\"\")\r\n        return pageList; // 必须要返回数据 ，格式：[{},{}];   否则直接退出\r\n\r\n    }\r\n    ,2 // 每页显示的数据条数\r\n    ,1 // 当前第几页，最小值为1\r\n    ,db.table(\'sys_role\').count() // 数据总条数\r\n    ,\"0,5,test1;6,11,test2\" // 这里表示，在开头第二行，合并0至5列并填写上内容 test1 ；再合并6至11列并填写上内容 test2\r\n    // ,\"0,5,test3;6,11,test4\" // 这里表示，在开头第三行，合并0至5列并填写上内容 test3 ；再合并6至11列并填写上内容 test4\r\n    // ... 根据情况自行设计\r\n ) ');
