INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/用户管理/个人信息修改.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"ebe40a0cf4b84192b6bbe923a0ecbd9c\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"4f0230049d7e4f39b1e0897cc0f46f9a\",\r\n  \"name\" : \"个人信息修改\",\r\n  \"createTime\" : 1760064784214,\r\n  \"updateTime\" : 1643713357950,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/center/update\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"{\\r\\n\\t\\r\\n}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport cn.dev33.satoken.secure.SaSecureUtil;\n\nvar oldPassword = db.selectValue(\"\"\"\n    select password from sys_user where id = #{id}\n\"\"\")\nif(oldPassword != SaSecureUtil.sha256(password)){\n    exit 0, \'原密码不正确！\'\n}\n\nvar data = {\n    id,\n    phone,\n    headPortrait\n}\nif(newPassword){\n    data.password = newPassword ? SaSecureUtil.sha256(newPassword) : \'\'\n}\nreturn db.table(\'sys_user\').primary(\'id\').update(data, true)\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/用户管理/保存.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"877918736c764253a85d0780cbd5f763\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"4f0230049d7e4f39b1e0897cc0f46f9a\",\r\n  \"name\" : \"保存\",\r\n  \"createTime\" : 1760064784220,\r\n  \"updateTime\" : 1754544092390,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/save\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"user:save\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"{\\n\\n}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ ]\r\n  },\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport cn.dev33.satoken.secure.SaSecureUtil;\n\nvar usernameCount = db.selectInt(\"select count(1) from sys_user where is_del = 0 and username = #{username} ?{id, and id != #{id}}\")\nif(usernameCount > 0){\n    exit 0,\'登录名称已存在\'\n}\n\npassword = password ? SaSecureUtil.sha256(password) : \'\'\nvar user = {\n    id,\n    name,\n    username,\n    password: password,\n    phone,\n    isLogin,\n    officeId,\n    headPortrait\n}\nif(id){\n    db.deleteCache(`permissions:${id}`)\n    db.update(\"\"\"\n        delete from sys_user_role where user_id = #{id}\n    \"\"\")\n}\nid = db.table(\"sys_user\").primary(\"id\").saveOrUpdate(user)\nfor(roleId in roles.split(\',\')){\n    db.table(\"sys_user_role\").column(\'user_id\', id).column(\"role_id\", roleId).insert()\n}');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/用户管理/修改登录状态.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"64ba47c2a11346e1972c63245cbf962c\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"4f0230049d7e4f39b1e0897cc0f46f9a\",\r\n  \"name\" : \"修改登录状态\",\r\n  \"createTime\" : 1760064784226,\r\n  \"updateTime\" : 1651932570354,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/change/login/status\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"user:change:login:status\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport cn.dev33.satoken.stp.StpUtil\n\nif(isLogin == \'1\'){\n    StpUtil.logout(id);\n}\nreturn db.table(\"sys_user\").column(\"isLogin\", isLogin).where().eq(\"id\",id).update()');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/用户管理/列表.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"4399f2eb199b46448aa98682fe792667\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"4f0230049d7e4f39b1e0897cc0f46f9a\",\r\n  \"name\" : \"列表\",\r\n  \"createTime\" : 1760064784231,\r\n  \"updateTime\" : 1753429360388,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/list\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"user:view\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"{\\n\\n}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 500,\\n    \\\"message\\\": \\\"系统内部出现错误\\\",\\n    \\\"data\\\": null,\\n    \\\"timestamp\\\": 1753429256724,\\n    \\\"executeTime\\\": 46\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ ]\r\n  },\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"code\",\r\n      \"value\" : \"402\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"凭证已过期\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"data\",\r\n      \"value\" : \"null\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"timestamp\",\r\n      \"value\" : \"1643964929030\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Long\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"executeTime\",\r\n      \"value\" : \"null\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nreturn db.page(\"\"\"\n    select\n        distinct\n        su.id,\n        su.username,\n        su.name,\n        IF(su.is_login = 0, \'false\', \'true\') is_login,\n        su.phone,\n        su.create_date,\n        su.office_id,\n        su.head_portrait,\n        so.name office_name,\n        (select group_concat(sr.name) from sys_role sr left join sys_user_role sur on sr.id = sur.role_id where sr.is_del = 0 and sur.user_id = su.id) roles\n    from sys_user su\n    left join sys_office so on su.office_id = so.id\n    left join sys_user_role sur on su.id = sur.user_id\n    where su.is_del = 0\n    ?{roleId, and sur.role_id in(#{roleId.split(\',\')})}\n    ?{officeId, and su.office_id in(#{officeId.split(\',\')})}\n    ?{username, and su.username like concat(\'%\',#{username},\'%\')}\n    ?{name, and su.name like concat(\'%\',#{name},\'%\')}\n    ?{isLogin, and su.is_login = #{isLogin}}\n    ?{orderByColumn, order by su.${orderByColumn} ${direction == 0 ? \'asc\' : direction == 1 ? \'desc\' : \'\'}}\n    ?{!orderByColumn, order by su.create_date desc}\n\"\"\")');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/用户管理/删除.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"c86e4f8fd4bc4d63bfaec8a53ea333cf\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"4f0230049d7e4f39b1e0897cc0f46f9a\",\r\n  \"name\" : \"删除\",\r\n  \"createTime\" : 1760064784236,\r\n  \"updateTime\" : 1754357703221,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/delete\",\r\n  \"method\" : \"DELETE\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"user:delete\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"{\\n\\n}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ ]\r\n  },\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \"@post:/file/delete/batch\" as fileBatchDelete; \nif(Arrays.asList(id.split(\',\')).contains(\'1\')){\n    exit 500, \'不允许删除超级管理员\'\n}\n\nfor(userId in id.split(\',\')){\n\n    var filePaths = db.select(\"\"\"\n        select head_portrait from sys_user where id = #{userId}\n    \"\"\").map(it => (it.headPortrait || \"[]\")::json.map(item => \'/\'+item.url).join(\',\')).join(\',\')\n       \n    if(filePaths != \"\"){\n        fileBatchDelete(filePaths);\n    }\n    db.deleteCache(`permissions:${userId}`)\n    // db.table(\"sys_user\").logic().where().eq(\"id\",userId).delete();\n    db.table(\"sys_user\").where().eq(\"id\",userId).delete();\n    db.update(\"\"\"\n        delete from sys_user_role where user_id = #{userId}\n    \"\"\")\n}\nreturn true');
