amp\",\r\n      \"value\" : \"1648866276963\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Long\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"executeTime\",\r\n      \"value\" : \"21\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport \"@post:/system/user/save\" as userSave;\nimport log\n\nbody.datas.each(data => {\n    var username\n    var name\n    var password\n    var phone\n    var officeId\n    var roles\n    var i = 0\n    data.each((key, value) => {\n        log.info(i + \'\')\n        if(i == 0){\n            username = value\n        }\n        if(i == 1){\n            password = value + \'\'\n        }\n        if(i == 2){\n            name = value\n        }\n        if(i == 3){\n            officeId = db.selectValue(\"\"\"\n                select id from sys_office where is_del = 0 and code = #{value}\n            \"\"\")\n            log.info(officeId)\n        }\n        if(i == 4){\n            roles = db.selectValue(\"\"\"\n                select id from sys_role where is_del = 0 and code = #{value}\n            \"\"\")\n            log.info(roles)\n        }\n        if(i == 5){\n            phone = value\n        }\n        i++\n    })\n    userSave()\n\n})\nreturn 1');
