         \"children\" : [ ]\r\n        }, {\r\n          \"name\" : \"code\",\r\n          \"value\" : \"\\\\n    <template>\\\\n      <mb-list ref=\\\\\\\"magicList\\\\\\\" v-bind=\\\\\\\"listOptions\\\\\\\" />\\\\n      <mb-dialog ref=\\\\\\\"formDialog\\\\\\\" @confirm-click=\\\\\\\"magicForm.save($event)\\\\\\\" width=\\\\\\\"50%\\\\\\\">\\\\n        <template #content>\\\\n          <mb-form ref=\\\\\\\"magicForm\\\\\\\" @reload=\\\\\\\"magicList.reload\\\\\\\" v-bind=\\\\\\\"formOptions\\\\\\\" />\\\\n        </template>\\\\n      </mb-dialog>\\\\n    </template>\\\\n    <script setup>\\\\n    import { ref, reactive, getCurrentInstance } from \'vue\'\\\\n    const { proxy } = getCurrentInstance()\\\\n    const formDialog = ref()\\\\n    const magicList = ref()\\\\n    const magicForm = ref()\\\\n    const listOptions = reactive({\\\\n        tools: [{\\\\n            type: \'add\',\\\\n            permission: \':data/test:save\',\\\\n            click: () => {\\\\n                formOptions.detail.formData = null\\\\n                formDialog.value.show()\\\\n            }\\\\n        }],\\\\n        table: {\\\\n            url: \'/data/test/list\',\\\\n            where: {\\\\n                name: {\\\\n                    label: \'名字\'\\\\n                },\\\\n                sex: {\\\\n                    label: \'性别\'\\\\n                },\\\\n                headPortrait: {\\\\n                    label: \'头像\'\\\\n                },\\\\n                remarks: {\\\\n                    label: \'备注\'\\\\n                }\\\\n            },\\\\n            cols: [\\\\n                {\\\\n                \\\\n                    field: \'name\',\\\\n                    label: \'名字\'\\\\n                },\\\\n                {\\\\n                    dictType: \'sex\',\\\\n                    field: \'sex\',\\\\n                    label: \'性别\'\\\\n                },\\\\n                {\\\\n                \\\\n                    field: \'headPortrait\',\\\\n                    label: \'头像\'\\\\n                },\\\\n                {\\\\n                \\\\n                    field: \'remarks\',\\\\n                    label: \'备注\'\\\\n                },{\\\\n                    label: \'操作\',\\\\n                    type: \'btns\',\\\\n                    width: 140,\\\\n                    fixed: \'right\',\\\\n                    btns: [\\\\n                        {\\\\n                            permission: \':data/test:save\',\\\\n                            label: \'修改\',\\\\n                            type: \'text\',\\\\n                            icon: \'ElEdit\',\\\\n                            click: (row) => {\\\\n                                magicForm.value.getDetail(row.id)\\\\n                                formDialog.value.show()\\\\n                            }\\\\n                        }, {\\\\n                            permission: \':data/test:delete\',\\\\n                            label: \'删除\',\\\\n                            type: \'text\',\\\\n                            icon: \'ElDelete\',\\\\n                            click: (row) => {\\\\n                                proxy.$common.handleDelete({\\\\n                                    url: \'/data/test/delete\',\\\\n                                    id: row.id,\\\\n                                    done: () => magicList.value.reload()\\\\n                                })\\\\n                            }\\\\n                        }\\\\n                    ]\\\\n                }\\\\n            ]\\\\n        }\\\\n    })\\\\n    \\\\n    const formOptions = reactive({\\\\n        detail: {\\\\n            request: {\\\\n              url: \'/data/test/get\'\\\\n            }\\\\n        },\\\\n        form: {\\\\n            request: {\\\\n                url: \\\\\\\"/data/test/save\\\\\\\",\\\\n                method: \\\\\\\"post\\\\\\\"\\\\n            },\\\\n            rows: [{\\\\n                gutter: 24,\\\\n                cols: [{\\\\n                    span: 12,\\\\n                    name: \'name\',\\\\n                    label: \'名字\',\\\\n                    component: \'input\'\\\\n                },{\\\\n                    span: 12,\\\\n                    name: \'sex\',\\\\n                    label: \'性别\',\\\\n                    component: \'radio-group\'\\\\n                },{\\\\n                    span: 12,\\\\n                    name: \'headPortrait\',\\\\n                    label: \'头像\',\\\\n                    component: \'upload-image\'\\\\n                },{\\\\n                    span: 12,\\\\n                    name: \'remarks\',\\\\n                    label: \'备注\',\\\\n                    component: \'input\',\\\\n                    props: {\\\\n                        type: \'textarea\'\\\\n                    }\\\\n      \\\\n                }]\\\\n            }]\\\\n        }\\\\n    })\\\\n\",\r\n          \"description\" : \"\",\r\n          \"required\" : false,\r\n          \"dataType\" : \"String\",\r\n          \"type\" : null,\r\n          \"defaultValue\" : null,\r\n          \"validateType\" : \"\",\r\n          \"error\" : \"\",\r\n          \"expression\" : \"\",\r\n          \"children\" : [ ]\r\n        } ]\r\n      } ]\r\n    }, {\r\n      \"name\" : \"timestamp\",\r\n      \"value\" : \"1648608988019\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Long\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"executeTime\",\r\n      \"value\" : \"24\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nreturn db.select(\"select name, compile_js, compile_css from sys_dynamic_component where is_del = 0 and compile_js is not null\")');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/组件/删除组件.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"da1bbeb256cf417cb26aaf2426ed58c3\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"6f106ebdee21489db34b956f7770ff03\",\r\n  \"name\" : \"删除组件\",\r\n  \"createTime\" : 1760064784301,\r\n  \"updateTime\" : 1710082768049,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/delete\",\r\n  \"method\" : \"DELETE\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"component:delete\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\n\nlet recursionDelete = (list) => {\n    list.forEach(it => {\n        db.table(\"sys_dynamic_component\").logic().where().eq(\"id\",it.id).delete()\n        let children = db.select(\"select id from sys_dynamic_component where is_del = 0 and pid = #{it.id}\")\n        if(children && children.size() > 0){\n            recursionDelete(children)\n        }\n    })\n}\nrecursionDelete(db.select(\"select id from sys_dynamic_component where is_del = 0 and pid = #{id}\"))\n\nreturn db.table(\"sys_dynamic_component\").logic().where().eq(\"id\",id).delete()');
