INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/组件/获取组件tree.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"8ba14d61082e4ba69324fdc9de080f38\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"6f106ebdee21489db34b956f7770ff03\",\r\n  \"name\" : \"获取组件tree\",\r\n  \"createTime\" : 1760064784324,\r\n  \"updateTime\" : 1712742831654,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/tree\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"component:tree\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nvar toTree = (list,pid) => select t.*,toTree(list,t.id) children from list t where t.pid = pid\nvar list = toTree(db.select(\"\"\"\n    select \n        dc.id,\n        (case when dc.remark is not null and dc.remark != \'\' then concat(dc.name,\'(\',dc.remark, \')\') else dc.name end) name,\n        dc.pid,\n        (case when dc.type = 0 then 1 else 0 end) is_group\n    from sys_dynamic_component dc\n    where dc.is_del = 0 \n    order by dc.name\n\"\"\"),\'0\')\n\nreturn {\n    list: list,\n    total: list.getLength()\n}');
