INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/菜单管理/保存.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"d6d05df1e8b14a6ebc270113b2cdd1ed\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"保存\",\r\n  \"createTime\" : 1760064784366,\r\n  \"updateTime\" : 1752206851856,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/save\",\r\n  \"method\" : \"POST\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"wrap_request_parameter\",\r\n    \"value\" : \"data\",\r\n    \"description\" : \"包装请求参数到一个变量中\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"menu:save\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"{}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 500,\\n    \\\"message\\\": \\\"系统内部出现错误\\\",\\n    \\\"data\\\": null,\\n    \\\"timestamp\\\": 1752206413023,\\n    \\\"executeTime\\\": 22\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ ]\r\n  },\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport \'@get:/system/menu/cache/delete\' as cacheDelete;\n\nif(data.url){\n    var urlCount = db.selectInt(\"select count(1) from sys_menu where is_del = 0 and url = #{data.url} ?{data.id, and id != #{data.id}}\")\n    if(urlCount > 0){\n        exit 0,\'菜单链接已存在\'\n    }\n}\nif(data.permission){\n    var permissionCount = db.selectInt(\"select count(1) from sys_menu where is_del = 0 and permission = #{data.permission} ?{data.id, and id != #{data.id}}\")\n    if(permissionCount > 0){\n        exit 0,\'权限标识已存在\'\n    }\n}\n\nvar result = db.table(\"sys_menu\").primary(\"id\").withBlank().saveOrUpdate(data);\n\ndb.deleteCache(\'permissions:1\')\nif(data.id){\n    var menuId = data.id\n    cacheDelete();\n}\nreturn result');
