n              \"name\" : \"meta\",\r\n              \"value\" : \"\",\r\n              \"description\" : \"\",\r\n              \"required\" : false,\r\n              \"dataType\" : \"Object\",\r\n              \"type\" : null,\r\n              \"defaultValue\" : null,\r\n              \"validateType\" : \"\",\r\n              \"error\" : \"\",\r\n              \"expression\" : \"\",\r\n              \"children\" : [ {\r\n                \"name\" : \"title\",\r\n                \"value\" : \"菜单管理\",\r\n                \"description\" : \"\",\r\n                \"required\" : false,\r\n                \"dataType\" : \"String\",\r\n                \"type\" : null,\r\n                \"defaultValue\" : null,\r\n                \"validateType\" : \"\",\r\n                \"error\" : \"\",\r\n                \"expression\" : \"\",\r\n                \"children\" : [ ]\r\n              }, {\r\n                \"name\" : \"icon\",\r\n                \"value\" : \"menu\",\r\n                \"description\" : \"\",\r\n                \"required\" : false,\r\n                \"dataType\" : \"String\",\r\n                \"type\" : null,\r\n                \"defaultValue\" : null,\r\n                \"validateType\" : \"\",\r\n                \"error\" : \"\",\r\n                \"expression\" : \"\",\r\n                \"children\" : [ ]\r\n              }, {\r\n                \"name\" : \"keepAlive\",\r\n                \"value\" : \"true\",\r\n                \"description\" : \"\",\r\n                \"required\" : false,\r\n                \"dataType\" : \"Boolean\",\r\n                \"type\" : null,\r\n                \"defaultValue\" : null,\r\n                \"validateType\" : \"\",\r\n                \"error\" : \"\",\r\n                \"expression\" : \"\",\r\n                \"children\" : [ ]\r\n              } ]\r\n            } ]\r\n          } ]\r\n        } ]\r\n      } ]\r\n    }, {\r\n      \"name\" : \"timestamp\",\r\n      \"value\" : \"1657368503505\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Long\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"executeTime\",\r\n      \"value\" : \"18\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nimport \'cn.dev33.satoken.stp.StpUtil\';\ntry {\n\n    var userId = StpUtil.getLoginId()\n    // 查出所有显示的菜单\n    var menus = db.select(\"\"\"\n    select\n        sm.id,\n        sm.name,\n        sm.pid,\n        sm.is_show,\n        sm.url,\n        sm.sort,\n        sm.icon,\n        sm.keep_alive,\n        sm.open_mode,\n        sm.component_name\n    from sys_menu sm \n    where 1=1\n    ?{userId != \'1\',\n        and sm.id in (\n            select menu_id from sys_role_menu where role_id in (\n                select role_id from sys_user_role where user_id = #{userId}\n            )\n        )\n    } and sm.is_del = \'0\' and sm.is_show = 1 order by sm.sort\n\"\"\")\n\n    return menus\n} catch (e) {\n    exit 500, e.message;\n}');
