INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/菜单管理/获取排序号.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"4f966df34dbe41ff8b9941da4671eb2d\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"获取排序号\",\r\n  \"createTime\" : 1760064784389,\r\n  \"updateTime\" : 1641732167291,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/sort\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ {\r\n    \"name\" : \"pid\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : true,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"options\" : [ ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nreturn db.selectInt(\"\"\"\n    select max(sort) + 10 from sys_menu where pid = #{pid} and is_del = \'0\'\n\"\"\") || 10;');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/菜单管理/获取组件树.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"038bc243ea494983b29124ae912f93d3\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"获取组件树\",\r\n  \"createTime\" : 1760064784393,\r\n  \"updateTime\" : 1752115344866,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/vue/compoment\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ ],\r\n  \"options\" : [ {\r\n    \"name\" : \"wrap_request_parameter\",\r\n    \"value\" : \"data\",\r\n    \"description\" : \"包装请求参数到一个变量中\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"permission\",\r\n    \"value\" : \"menu:change\",\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : null,\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : null,\r\n  \"responseBodyDefinition\" : null\r\n}\r\n================================\r\nimport request;\r\n\r\nvar transformTreeData = (data) =>{\r\n  // 递归处理每个节点\r\n  var processNode = (node) =>{\r\n    var newNode = {\r\n      id: node.node.id,\r\n      parentId: node.node.parentId,\r\n      name: node.node.name,\r\n      children: []\r\n    };\r\n    \r\n    // 如果有子节点，递归处理\r\n    if (node.children && node.children.length > 0) {\r\n      newNode.children = node.children.map(child => processNode(child));\r\n    }\r\n    \r\n    return newNode;\r\n  }\r\n  \r\n  // 处理顶层节点\r\n  return data.map(item => processNode(item));\r\n}\r\n\r\nvar mergeDirsAndFiles = (dirs, files) =>{\r\n    // 首先处理目录的深拷贝\r\n    const clonedDirs = dirs::stringify::json;\r\n    \r\n    // 创建一个映射表方便查找节点\r\n    const nodeMap = {};\r\n    var buildMap = (nodes) =>{\r\n        nodes.forEach(node => {\r\n            nodeMap[node.id] = node;\r\n            if (node.children) {\r\n                buildMap(node.children);\r\n            }\r\n        });\r\n    }\r\n    buildMap(clonedDirs);\r\n    \r\n    // 将文件添加到对应的目录中\r\n    files.forEach(file => {\r\n        const parentNode = nodeMap[file.parentId];\r\n        if (parentNode) {\r\n            if (!parentNode.children) {\r\n                parentNode.children = [];\r\n            }\r\n            parentNode.children.push({\r\n                ...file,\r\n               // isFile: true  // 添加标记区分文件和目录\r\n            });\r\n        }\r\n    });\r\n    \r\n    return clonedDirs;\r\n}\r\n\r\nreturn mergeDirsAndFiles(\r\n    transformTreeData(request.service().tree(\'vue\').children),\r\n    request.service().files(\'vue\').map(child => {\r\n        id: child.id,\r\n        parentId: child.groupId,\r\n        name: child.name\r\n    })\r\n)\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/api/系统管理/菜单管理/获取菜单tree.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"ffb6988226d14e6789cc30193e008183\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"67b2ce258e24491194b74992958c74aa\",\r\n  \"name\" : \"获取菜单tree\",\r\n  \"createTime\" : 1760064784397,\r\n  \"updateTime\" : 1752031439791,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/tree\",\r\n  \"method\" : \"GET\",\r\n  \"parameters\" : [ {\r\n    \"name\" : \"orderBy\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"options\" : [ {\r\n    \"name\" : null,\r\n    \"value\" : null,\r\n    \"description\" : \"允许拥有该权限的访问\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ],\r\n  \"requestBody\" : \"{\\n\\n}\",\r\n  \"headers\" : [ ],\r\n  \"paths\" : [ ],\r\n  \"responseBody\" : \"{\\n    \\\"code\\\": 402,\\n    \\\"message\\\": \\\"凭证已过期\\\",\\n    \\\"data\\\": null,\\n    \\\"timestamp\\\": 1709773777522,\\n    \\\"executeTime\\\": null\\n}\",\r\n  \"description\" : null,\r\n  \"requestBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ ]\r\n  },\r\n  \"responseBodyDefinition\" : {\r\n    \"name\" : \"\",\r\n    \"value\" : \"\",\r\n    \"description\" : \"\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"Object\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : \"\",\r\n    \"error\" : \"\",\r\n    \"expression\" : \"\",\r\n    \"children\" : [ {\r\n      \"name\" : \"code\",\r\n      \"value\" : \"402\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Integer\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"message\",\r\n      \"value\" : \"凭证已过期\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"String\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"data\",\r\n      \"value\" : \"null\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"timestamp\",\r\n      \"value\" : \"1634309660370\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Long\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    }, {\r\n      \"name\" : \"executeTime\",\r\n      \"value\" : \"null\",\r\n      \"description\" : \"\",\r\n      \"required\" : false,\r\n      \"dataType\" : \"Object\",\r\n      \"type\" : null,\r\n      \"defaultValue\" : null,\r\n      \"validateType\" : \"\",\r\n      \"error\" : \"\",\r\n      \"expression\" : \"\",\r\n      \"children\" : [ ]\r\n    } ]\r\n  }\r\n}\r\n================================\r\nvar toTree = (list,pid) => select t.*,toTree(list,t.id) children from list t where t.pid = pid\n\nvar list = toTree(db.select(\"\"\"\n    select \n        sm.id,\n        sm.name,\n        sm.pid,\n        IF(sm.is_show = 1, \'true\', \'false\') AS is_show, \n        sm.url,\n        sm.sort,\n        sm.permission,\n        sm.desc_ribe,\n        sm.icon,\n        sm.keep_alive,\n        sm.component_name,\n        sm.open_mode \n    from sys_menu sm\n    where sm.is_del = 0 ${orderBy}\n\"\"\"),\'0\')\n\nreturn {\n    list: list,\n    total: list.getLength()\n}');
