INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/function/工具/字符串转MD5.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"2b256af3ff154e179dd17adaa30534e4\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"31c4ca06b0ef455ea7a5847bf71e472d\",\r\n  \"name\" : \"字符串转MD5\",\r\n  \"createTime\" : 1760064784590,\r\n  \"updateTime\" : 1749362540257,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"buildMD5\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"input\",\r\n    \"value\" : null,\r\n    \"description\" : \"需要加密的字符串\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport java.security.MessageDigest\r\n\r\n // 获取 MD5 实例\r\nMessageDigest md = MessageDigest.getInstance(\"MD5\");\r\n\r\n// 进行哈希计算\r\nvar digest = md.digest(input.getBytes());\r\n\r\n// 转换为 16 进制字符串（小写）\r\nStringBuilder hexString = new StringBuilder();\r\nfor ( b in digest) {\r\n    hexString.append(String.format(\"%02x\", b & 0xff));\r\n}\r\n\r\nreturn hexString.toString(); // 返回 32 位小写 MD5');
