INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/function/权限/指派接口开发权限.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"c82f8158b08c44eb9af297890e7d260d\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"41922e26ef57421f8819fe6c59f14d63\",\r\n  \"name\" : \"指派接口开发权限\",\r\n  \"createTime\" : 1765189922731,\r\n  \"updateTime\" : null,\r\n  \"lock\" : null,\r\n  \"createBy\" : \"管理员\",\r\n  \"updateBy\" : \"管理员\",\r\n  \"path\" : \"dispatch/api/dev/user\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"rootPath\",\r\n    \"value\" : null,\r\n    \"description\" : \"接口的根目录的路径\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"paths\",\r\n    \"value\" : null,\r\n    \"description\" : \"接口的具体路径列表，多个用逗号（,）隔开\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"username\",\r\n    \"value\" : null,\r\n    \"description\" : \"指派给谁就是谁的名称如：徐海洋，这里就只能是一个人的名称\",\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nimport http;\r\nreturn http.connect(\'http://127.0.0.1:9999/resources/dispatchApiDevUser\')\r\n    .data({\r\n        \"type\": \'api\',\r\n        \"rootPath\": rootPath,//\'plugin\',\r\n        \"paths\": paths, //\"plugin/mqtt/cluster/unsubscribe,plugin/mqtt/cluster/publish\",\r\n        \"username\": username //\"徐海洋\"\r\n    })\r\n    .post().getBody();\r\n');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/function/权限/组织机构.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"a5f80b11b7fb4f3c97252331c80bcf85\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"41922e26ef57421f8819fe6c59f14d63\",\r\n  \"name\" : \"组织机构\",\r\n  \"createTime\" : 1760064784599,\r\n  \"updateTime\" : 1752409918327,\r\n  \"lock\" : \"0\",\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/office\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : \"/permission/office\",\r\n  \"parameters\" : [ ]\r\n}\r\n================================\r\nimport \'cn.dev33.satoken.stp.StpUtil\';\n\nvar currentUserId = StpUtil.getLoginId()\n//查出当前用户有多少角色\nvar roles = db.select(\"\"\"\n    select permission from sys_role where is_del = 0 and id in (select role_id from sys_user_role where user_id = #{currentUserId})\n\"\"\")\nvar userIds = []\nfor(role in roles){\n    if(role.permission == \'0\'){\n        return [] // 所有数据我都能访问\n    }else if(role.permission == \'1\'){\n        userIds.addAll(db.select(\"\"\"\n            select id from sys_user where is_del = 0 and office_id in (\n                select office_id from sys_role_office where role_id in (\n                    select role_id from sys_user_role where user_id = #{currentUserId}\n                )\n            )\n        \"\"\").map(it => it.id))  // 我能访问被设置的机构对应的人员创建的数据\n    }else if(role.permission == \'3\'){\n        var officeId = db.selectValue(\"select office_id from sys_user where id = #{currentUserId}\")\n        var offices = []\n        offices.push(officeId)\n        userIds.addAll(db.select(\"select id from sys_user where office_id in (#{offices})\").map(it => it.id))  // 我能访问同机构的 用户创建的数据\n    }else{\n        var officeId = db.selectValue(\"select office_id from sys_user where id = #{currentUserId}\")\n        var offices = []\n        offices.push(officeId)\n        var getOfficeId = (list,pid) => {\n            var ids = select t.id from list t where t.pid = pid;\n            for(it in ids){\n                offices.push(it.id)\n                getOfficeId(list,it.id)\n            }\n        }\n        getOfficeId(db.select(\'select id, pid from sys_office where is_del = 0 order by sort\'),officeId)\n        userIds.addAll(db.select(\"select id from sys_user where office_id in (#{offices})\").map(it => it.id))  // 我能访问同机构及被设置的机构的子机构的 用户创建的数据\n    }\n}\n\nreturn userIds');
