INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/function/配置中心/根据keyAndcondition获取数据值.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"copy1653111178446d65648\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"7e31035eb8d4471b9fc2923ea1d966c3\",\r\n  \"name\" : \"根据keyAndcondition获取数据值\",\r\n  \"createTime\" : 1760064784602,\r\n  \"updateTime\" : 1653118303409,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getBykeyCondition\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"configureKey\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"configureCondition\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nvar configure = db.cache(`configure:${configureKey}${configureCondition}`).selectOne(\"\"\"\n     select configure_value from sys_configure where configure_key = #{configureKey} \n     ?{configureCondition, and configure_condition = #{configureCondition}}\n\"\"\")\n\nreturn configure == null ? \"\" : configure.get(\"configureValue\")');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/function/配置中心/根据keyLikeCondition获取数据值.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"copy1653112036134d44643\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"7e31035eb8d4471b9fc2923ea1d966c3\",\r\n  \"name\" : \"根据keyLikeCondition获取数据值\",\r\n  \"createTime\" : 1760064784605,\r\n  \"updateTime\" : 1653118334978,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getLikeCondition\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"configureKey\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  }, {\r\n    \"name\" : \"configureCondition\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : null,\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nvar configure = db.cache(`configure:${configureKey}${configureCondition}`).selectOne(\"\"\"\n     select configure_value from sys_configure where configure_key = #{configureKey} \n     ?{configureCondition, and configure_condition like concat(\'%\',#{configureCondition},\'%\')}\n\"\"\")\n\nreturn configure == null ? \"\" : configure.get(\"configureValue\")');
INSERT INTO `magic_api_file_v2` VALUES ('/magic-api/function/配置中心/根据key获取数据值.ms', '{\r\n  \"properties\" : { },\r\n  \"id\" : \"3a21cd5fcd9b4e96b870a2268088266d\",\r\n  \"script\" : null,\r\n  \"groupId\" : \"7e31035eb8d4471b9fc2923ea1d966c3\",\r\n  \"name\" : \"根据key获取数据值\",\r\n  \"createTime\" : 1760064784608,\r\n  \"updateTime\" : 1653119091752,\r\n  \"lock\" : null,\r\n  \"createBy\" : null,\r\n  \"updateBy\" : null,\r\n  \"path\" : \"/getBykey\",\r\n  \"description\" : null,\r\n  \"returnType\" : null,\r\n  \"mappingPath\" : null,\r\n  \"parameters\" : [ {\r\n    \"name\" : \"configureKey\",\r\n    \"value\" : null,\r\n    \"description\" : null,\r\n    \"required\" : false,\r\n    \"dataType\" : \"String\",\r\n    \"type\" : \"java.lang.String\",\r\n    \"defaultValue\" : null,\r\n    \"validateType\" : null,\r\n    \"error\" : null,\r\n    \"expression\" : null,\r\n    \"children\" : null\r\n  } ]\r\n}\r\n================================\r\nvar configure = db.cache(`configure:${configureKey}`).selectOne(\"\"\"\n     select configure_value from sys_configure where configure_key = #{configureKey}\n\"\"\")\nreturn configure == null ? \"\" : configure.get(\"configureValue\")');
